from pathlib import Path
import json
p=Path(__file__).with_name('language-curriculum.json');d=json.loads(p.read_text())
bank={
'intro':[['graphical elements','The visible ingredients a designer uses.','Line, color, and type are graphical elements.'],['arranged to','Connect organisation with its purpose.','The elements are arranged to make the invitation clear.'],['communicate a message','Help an audience understand something.','This poster communicates the opening details.']],
'line':[['separates … from …','Describe a useful division.','The line separates the date from the location.'],['a dividing line','A line placed between different information.','I added a dividing line.'],['between the details','Locate the divider.','The line sits between the two details.']],
'color':[['stands out','Gets more attention than nearby elements.','The offer stands out in the accent color.'],['an accent color','A color used for selective emphasis.','We can use an accent color for the offer.'],['keep unchanged','Do not alter an agreed feature.','I will keep the logo colors unchanged.']],
'shape':[['a curved outline','A boundary made with a curve.','The circle has a curved outline.'],['two-dimensional','Describes a flat area rather than volume.','This is a two-dimensional shape.'],['at a small size','When the mark is reduced.','Test the outline at a small size.']],
'texture':[['looks textured','Describes an appearance, not a proven physical feel.','The surface looks textured.'],['suggests texture','Creates a visual impression of a surface.','The printed pattern suggests texture.'],['keep the name clear','Preserve readability while adding detail.','I can add texture and keep the name clear.']],
'space':[['more empty space','A larger unoccupied area.','There is more empty space around the headline.'],['around the headline','On the sides of the main text.','I added space around the headline.'],['not enough room','Too little space for the content.','There is not enough room between the pictures.']],
'form':[['makes it look','Connect a visual change to an appearance.','The shading makes it look rounded.'],['light and shadow','Lighter and darker areas suggesting depth.','Light and shadow suggest a rounded form.'],['three-dimensional','Having or suggesting volume and depth.','The ball looks three-dimensional.']],
'typography':[['the wording stays the same','The actual words are unchanged.','The wording stays the same in both versions.'],['type style','The appearance of the letters.','The type style changes.'],['compare the letterforms','Look at the design of the letters.','Compare the letterforms before choosing.']],
'contrast':[['different from','Make a comparison between unlike features.','The dark circle is different from the others.'],['darker than','Compare lightness.','The middle circle is darker than its neighbors.'],['stronger contrast','A greater visible difference.','We can use stronger contrast for the main option.']],
'hierarchy':[['stands out first','Receives the earliest or strongest attention.','The invitation stands out first.'],['comes next','Follows in the intended order of attention.','The practical information comes next.'],['an order of importance','A hierarchy of stronger and weaker emphasis.','The sizes create an order of importance.']],
'alignment':[['line up','Share a visible edge or guide.','The text blocks line up.'],['along the same edge','Use one common boundary.','The blocks line up along the same left edge.'],['a shared guide','A reference that connects positions.','I aligned the headings to a shared guide.']],
'balance':[['visual weight','How strongly an element occupies attention.','The large shapes carry more visual weight.'],['on both sides','Spread across the two parts of the frame.','The shapes are on both sides.'],['asymmetrical balance','Balance without identical arrangements.','Unequal elements can create asymmetrical balance.']],
'proximity':[['closer together','With a smaller gap between related items.','The date and time are closer together.'],['related details','Information that belongs to the same useful group.','Keep related details together.'],['grouped with','Placed near something it belongs with.','The address is grouped with the location.']],
'repetition':[['repeats across','Appears again in several items.','The same style repeats across the cards.'],['the same type style','Consistent letter presentation.','Use the same type style for the headings.'],['consistent with','Matches the chosen visual system.','This card is consistent with the other two.']],
'simplicity':[['remove extra decoration','Take away details the message does not need.','I removed extra decoration.'],['essential information','The facts needed to understand or act.','The date and location are essential information.'],['without losing','Keep something useful while making a change.','Simplify without losing the opening details.']],
'function':[['helps people','Connect a design to what the audience can do.','The poster helps people find the event.'],['meets the brief','Satisfies the agreed requirements.','This version meets the brief.'],['communication goal','What the audience should understand or do.','Attendance is the communication goal.']]
}
for t in d['foundations']:t['chunks']=bank[t['concept']]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2));print('Authored concept-specific language chunks for all foundation rounds')
